import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"亮马河国际风情水岸","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/liangma-river.md","filePath":"landmarks/liangma-river.md","lastUpdated":1787033866000}'),n={name:"landmarks/liangma-river.md"};function d(o,t,i,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="亮马河国际风情水岸" tabindex="-1">亮马河国际风情水岸 <a class="header-anchor" href="#亮马河国际风情水岸" aria-label="Permalink to &quot;亮马河国际风情水岸&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200" alt="亮马河国际风情水岸"></p><blockquote><p>&quot;一河碧水穿城过，光影璀璨夜京城。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>亮马河国际风情水岸位于北京市朝阳区，是围绕亮马河沿线打造的滨水休闲空间。经过综合治理与景观提升，亮马河两岸绿道、亲水平台、商业街区和灯光景观融为一体，白天可以散步骑行，夜晚灯光与水景交相辉映。沿河还开通了夜航游船，可以从水上欣赏国贸CBD、三里屯使馆区的都市夜景，是北京新晋的城市观光目的地。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放（游船按班次运营）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">沿岸免费，游船收费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-3小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">春秋季，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁10号线亮马桥站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市朝阳区亮马河沿线</td></tr></tbody></table><h2 id="景观特色" tabindex="-1">景观特色 <a class="header-anchor" href="#景观特色" aria-label="Permalink to &quot;景观特色&quot;">​</a></h2><h3 id="滨水绿道与亲水平台" tabindex="-1">滨水绿道与亲水平台 <a class="header-anchor" href="#滨水绿道与亲水平台" aria-label="Permalink to &quot;滨水绿道与亲水平台&quot;">​</a></h3><p>亮马河两岸修建了连续的滨水步道和亲水平台，绿树成荫，是散步、慢跑、遛娃的好去处。</p><h3 id="国际风情商业街区" tabindex="-1">国际风情商业街区 <a class="header-anchor" href="#国际风情商业街区" aria-label="Permalink to &quot;国际风情商业街区&quot;">​</a></h3><p>沿岸分布着三里屯、蓝色港湾等商圈，以及众多餐厅、咖啡馆，可以边看风景边用餐。</p><h3 id="夜景灯光秀" tabindex="-1">夜景灯光秀 <a class="header-anchor" href="#夜景灯光秀" aria-label="Permalink to &quot;夜景灯光秀&quot;">​</a></h3><p>夜晚亮马河两岸灯光点亮，桥梁与建筑倒映水中，构成绚丽的城市夜景，是拍照打卡的绝佳地点。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="夜航游船" tabindex="-1">夜航游船 <a class="header-anchor" href="#夜航游船" aria-label="Permalink to &quot;夜航游船&quot;">​</a></h3><p>从燕莎码头乘船夜游亮马河，航线经过蓝港商圈与使馆区，全程约40分钟，是感受北京都市夜景的新方式。</p><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>亮马桥站 → 滨水绿道漫步 → 蓝色港湾 → 沿河向东 → 夜航游船</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>最佳时间</strong>：华灯初上时最漂亮，建议黄昏后到达</li><li><strong>游船</strong>：船票需提前预约，注意运营时间</li><li><strong>餐饮</strong>：沿岸及蓝色港湾内有众多餐厅，可安排用餐</li><li><strong>交通</strong>：地铁10号线亮马桥站、农业展览馆站均可到达</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">10号线亮马桥站或农业展览馆站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">东三环沿线公交站步行可达</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;亮马桥&quot;或&quot;燕莎码头&quot;</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">三里屯太古里</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">潮流时尚街区</td></tr><tr><td style="text-align:left;">蓝色港湾</td><td style="text-align:center;">步行10分钟</td><td style="text-align:left;">欧式风情商圈</td></tr><tr><td style="text-align:left;">朝阳公园</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">城市大公园</td></tr><tr><td style="text-align:left;">北京CBD</td><td style="text-align:center;">车程10分钟</td><td style="text-align:left;">摩天大楼夜景</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>亮马河国际风情水岸体现了北京城市水岸空间的活化升级，将原本封闭的河道打开为市民共享的滨水公共空间，是&quot;水城共生&quot;的城市更新典范。</p><hr><p><strong>📍 地址</strong>：北京市朝阳区亮马河沿线 <strong>🚇 地铁</strong>：10号线亮马桥站</p><p><strong>💡 Tips</strong>：夜航游船需要提前预约，旺季一定要早点订票。</p>',31)])])}const c=e(n,[["render",d]]);export{f as __pageData,c as default};
